-- made by @kylosilly >.<
local replicated_storage = game:GetService("ReplicatedStorage");

local notify_picklock = replicated_storage.Network.RemoteEvents.NotifyOfLockpickFailed;
local open_gate = replicated_storage.Network.RemoteEvents.LockpickGateOpen;

getgenv().lol = not getgenv().lol;

repeat
    for _, plot in workspace.ActivePlots:GetChildren() do
        local plot_name = plot.Name;
        if (plot_name == "Plot") then
            continue;
        end;
        if (plot_name == tostring(game:GetService("Players").LocalPlayer.UserId)) then
            continue; -- remove these 3 lines if you wanna do it to yourself too fr
        end;
        if (not plot:GetAttribute("LockDuration")) then
            open_gate:FireServer(plot, 9e999);
        end;
        notify_picklock:FireServer(plot);
    end;
    task.wait(.1);
until (not getgenv().lol);

-- made by @kylosilly on discord
local replicated_storage = game:GetService("ReplicatedStorage");
local start = replicated_storage.Network.RemoteFunctions.StartDigging;
local finish = replicated_storage.Network.RemoteEvents["0a1baf564dbb5375"];
local ending = replicated_storage.Network.RemoteEvents.EndDigging;

getgenv().sigma = not getgenv().sigma;

repeat
	start:InvokeServer();
	task.wait(1);
	finish:FireServer(1);
	task.wait(1);
	ending:FireServer("Succeeded");
	task.wait(1);
until (not getgenv().sigma);

